      html: '<button class="btn btn-primary" (click)="open()">Open the Wizard</button>\n\n<clr-wizard #wizard [(clrWizardOpen)]="_open">\n  <clr-wizard-title>Wizard Title</clr-wizard-title>\n\n  <clr-wizard-button type="cancel">Cancel</clr-wizard-button>\n  <clr-wizard-button type="previous">Back</clr-wizard-button>\n  <clr-wizard-button type="next">Next</clr-wizard-button>\n  <clr-wizard-button type="finish">Finish</clr-wizard-button>\n\n  @for (page of pages; track $index; let i = $index) { @if (!page.skipped) {\n  <clr-wizard-page>\n    <ng-template clrPageTitle>Page {{ i + 1 }}</ng-template>\n    Content for page {{ i + 1 }}\n  </clr-wizard-page>\n  } }\n</clr-wizard>\n',
